fn intersperse(numbers: &[i32], delim: i32) -> Vec<i32> {
    if numbers.is_empty() {
        return Vec::new();
    }

    // The resulting length when interspersing delimiter between elements is 2*n - 1
    let n = numbers.len();
    let mut result = Vec::with_capacity(2 * n - 1);

    for (i, &num) in numbers.iter().enumerate() {
        if i > 0 {
            result.push(delim);
        }
        result.push(num);
    }

    result
}